#include <stdio.h>  

int main(void)
{
    FILE *file = fopen("cs50.txt", "w");
    if (file == NULL)
    {
        return 0;
    }

    char *s = "This is CS50";
    fprintf(file, "%s\n", s);

    int i = 50;
    fprintf(file, "This is CS%i\n", i);

